def born_weights(amplitudes: Mapping[L, float]) -> Dict[L, float]:
    norm_sq = sum(a * a for a in amplitudes.values())
    if norm_sq == 0.0:
        raise ValueError("zero state")
    return {label: a * a / norm_sq for label, a in amplitudes.items()}

if __name__ == "__main__":
    for k in (1, 2, 3, 5):
        e = 10.0 ** (-k)
        print(k, born_weights({"0": 1.0, "1": e}))

from __future__ import annotations
from typing import Tuple

def equal_pair(amplitude: float) -> Tuple[float, float]:
    if amplitude == 0.0:
        raise ValueError("nonzero amplitude required")
    norm_sq = 2.0 * amplitude * amplitude
    return amplitude * amplitude / norm_sq, amplitude * amplitude / norm_sq

if __name__ == "__main__":
    for amplitude in (0.01, 1.0, 17.0):
        print(amplitude, equal_pair(amplitude))

from __future__ import annotations
from fractions import Fraction
from typing import Tuple
Lex = Tuple[Fraction, Fraction]

def event_weight(n: int, k: int, reservoir: bool) -> Lex:
    if not (0 <= k <= n):
        raise ValueError("require 0 <= k <= n")
    return (Fraction(1), Fraction(k - n)) if reservoir else (Fraction(0), Fraction(k))

def standard_part(weight: Lex) -> Fraction:
    return weight[0]

if __name__ == "__main__":
    for reservoir in (False, True):
        for k in range(4):
            w = event_weight(3, k, reservoir)
            print(reservoir, k, w, standard_part(w))

